.action-input:focus{outline:none;border-color:var(--c-gold)}
.battle-btn{width:100%;margin-top:8px;padding:8px 0;border-radius:7px;border:none;background:linear-gradient(90deg,var(--c-accent),#c44550);color:#fff;font-size:13px;font-weight:700;cursor:pointer;transition:opacity .15s ease}
.battle-btn:hover{opacity:.9}
