  .skill-sel{grid-template-columns:repeat(2,1fr)}
  .detail{padding:8px 9px}
  .d-sec{padding:7px 8px}
  .d-sec .d-title{font-size:11px}
  .kv{font-size:11px;padding:4px 0}
  .body-grid{grid-template-columns:repeat(2,1fr)}
  .action-input{min-height:52px;font-size:13px}
  .battle-btn{padding:11px 0;font-size:14px}
  .her-item-mini .him{font-size:11px;padding:4px 9px}
}
@media(max-width:360px){
  .roster-grid{grid-template-columns:1fr}
  .skill-grid{grid-template-columns:1fr}
  .subjects{grid-template-columns:1fr}
  .body-grid{grid-template-columns:1fr}
  .stats-top{flex-direction:column;align-items:stretch}
}
</style>
</head>
