function deepMergeStat(dst,src){
  if(!src||typeof src!=='object')return dst;
  var out={};try{out=JSON.parse(JSON.stringify(dst||{}))}catch(e){out={}}
  for(var k in src){
    if(!Object.prototype.hasOwnProperty.call(src,k))continue;
    var sv=src[k],dv=out[k];
    if(sv&&typeof sv==='object'&&!Array.isArray(sv)&&dv&&typeof dv==='object'&&!Array.isArray(dv)){out[k]=deepMergeStat(dv,sv)}
    else{out[k]=sv}
  }
  return out;
}
// 读变量用【最新楼】（skill 读取降级链：最新assistant楼/latest 优先——技能升级/战斗结算都发生在最新楼，状态栏在任何楼层都要能读到）
// 写回仍用 getMessageOption()（自己楼层，见 ensureSchedule/advancePhysio——写回不能改 latest 会破坏目标楼层）
function getReadOption(){return{type:'message',message_id:'latest'}}
function readStatData(){
  var stat=null;
  // ★第一优先：战斗系统.js（TH 脚本）中继到主页面的最新 stat_data——消息环境拿不到 TH API 时这是唯一可靠通路（skill 坑#27：常驻脚本捕获→全局中继→界面纯读）
  try{var relay=(window.__ydsLatestStat&&window.__ydsLatestStat.stat_data)?window.__ydsLatestStat.stat_data:null;if(relay&&hasData(relay))stat=relay}catch(e){}
  if(!stat){try{var Mvu2=getMvu();if(Mvu2&&typeof Mvu2.getMvuData==='function'){stat=pickStatData(Mvu2.getMvuData(getReadOption()))}}catch(e){}}
  if(!stat){try{var gv=pickHostFn('getVariables');if(gv){stat=pickStatData(gv(getReadOption()))}}catch(e){}}
  if(!stat&&cachedStatFromBridge&&hasData(cachedStatFromBridge))stat=cachedStatFromBridge;
  if(!stat){var embedded=parseEmbeddedStat();if(embedded)stat=embedded}
  if(!stat){try{var gav=pickHostFn('getAllVariables');if(gav){stat=pickStatData(gav())}}catch(e){}}
  return deepMergeStat(DEFAULT_STAT,stat||{});
}
function requestStatFromBridge(){
  var mesId=resolveMessageId();var payload={type:'yds-mvu-stat-request',messageId:mesId};
  for(var i=0;i<TH_HOSTS.length;i++){try{TH_HOSTS[i].postMessage(payload,'*')}catch(e){}}
}
function waitForReadableStat(timeoutMs,cb){
  timeoutMs=timeoutMs||6000;var started=Date.now();
  (function poll(){
    var stat=readStatData();
    if(Object.keys(stat).length>0){cb(stat);return}
    requestStatFromBridge();
    if(Date.now()-started<timeoutMs){setTimeout(poll,180)}else{cb(readStatData())}
  })();
}

/* 工具 */
function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function num(v,d){if(Array.isArray(v))v=v[0];v=parseFloat(v);d=(d===undefined)?0:d;return isNaN(v)?d:v}
function pct(v,max){v=num(v,0);max=num(max,100);return Math.max(0,Math.min(100,max>0?(v/max)*100:0))}
function clamp(v,min,max){v=num(v,0);return Math.max(min,Math.min(max,v))}
function kv(k,v,cls){return '<div class="d-line"><span>'+k+'</span><b'+(cls?' style="color:'+cls+'"':'')+'>'+esc(v)+'</b></div>'}
function bar(label,val,max,color){
  max=max||100;var v=clamp(val,0,max);
  var c=color||(v>=80?'linear-gradient(90deg,#e0525e,#ff8a95)':v>=40?'linear-gradient(90deg,#d9a441,#e8c77a)':'linear-gradient(90deg,#6aa8d8,#a8d4f0)');
  return '<div class="hp-row" style="margin-top:6px"><span class="hp-label">'+label+'</span><div class="hp-track"><div class="hp-fill'+(v<=15?' hp-low':'')+'" style="width:'+pct(v,max)+'%;background:'+c+'"></div></div><span class="hp-num">'+v+'/'+max+'</span></div>';
}
function miniBar(v,color){return '<span class="mini-bar"><i style="width:'+clamp(v,0,100)+'%;background:'+color+'"></i></span>'}
function psyBar(v,color){return '<i style="width:'+clamp(v,0,100)+'%;background:'+color+'"></i>'}
function secTitle(t,nsfw){return '<div class="d-sec-title">'+t+(nsfw?' <span class="nsfw-tag">NSFW</span>':'')+'</div>'}
function obj(o){return(o&&typeof o==='object')?o:{}}
function skillDesc(key){
  var m={
    螺旋:'效果 Lv×1.5；每回合叠加麻痒点，麻痒≥5 触发她失神 1 回合（防守值-5）',
    颗粒:'效果 Lv×1；刺激加深，她本回合减伤-1/回合',
