/* 她的道具栏渲染 */
function playerPhysioTags(p){
  var ph=obj(p.生理);
  var ejCd=num(ph.射精冷却剩余,0);
  var ejCnt=num(ph.今日射精次数,0);
  var tags='';
  // 不应期（射精冷却）：日常不按回合计，只显示状态与效果（数值恢复看性欲/体力/跨日）
  if(ejCd>0){tags+='<span class="ps-item" style="color:var(--c-warn)">🔒 不应期（射精后）：伤害×'+(ejCd>=3?'0.6':(ejCd===2?'0.75':'0.9'))+' · 勃起上限减半</span>';}
  // 今日射精次数
  tags+='<span class="ps-item" style="color:var(--c-dim)">💦 今日射精 '+ejCnt+' 次</span>';
  // 完全无法勃起（性欲<20 且勃起0）——硬限制标记
  if(num(p.性欲,0)<20&&num(p.勃起度,0)<=0){tags+='<span class="ps-item" style="color:var(--c-danger)">⛔ 性欲不足·无法勃起（主动开战被拒；被动被拉入=被动承受）</span>';}
  else if(num(p.性欲,0)<40){tags+='<span class="ps-item" style="color:var(--c-warn)">⚠️ 勉强（性欲'+num(p.性欲,0)+'，勃起上限40）</span>';}
  // 体力透支
  if(num(p.体力,0)<30){tags+='<span class="ps-item" style="color:var(--c-danger)">🥵 体力透支（<30，战斗力-50%）</span>';}
  return tags?'<span class="ps">'+tags+'</span>':'';
}
