function profileText(name){
  var a=profileOf(name);
  var html='';
  // 性格反差（表/里）——表=正常色、里=粉色强调，最显眼的位置
  var sx=(typeof YDS_FIXED_SEX==='object'&&YDS_FIXED_SEX)?(YDS_FIXED_SEX[name]||{}):{};
