  }
  if(a.敏感带||a.节奏||a.体位||a.高潮||a.羞点){
    html+='<div class="psy-row" style="margin-bottom:6px"><span class="psy" style="color:var(--c-powder)">❤️ 性癖</span></div>';
    if(a.敏感带)html+='<div class="d-text"><b style="color:var(--c-powder)">敏感带</b> '+esc(a.敏感带)+'</div>';
    if(a.节奏)html+='<div class="d-text"><b style="color:var(--c-powder)">节奏</b> '+esc(a.节奏)+'</div>';
    if(a.体位)html+='<div class="d-text"><b style="color:var(--c-powder)">体位</b> '+esc(a.体位)+'</div>';
    if(a.高潮)html+='<div class="d-text"><b style="color:var(--c-powder)">高潮</b> '+esc(a.高潮)+'</div>';
    if(a.羞点)html+='<div class="d-text"><b style="color:var(--c-powder)">羞点</b> '+esc(a.羞点)+'</div>';
  }
  if(a.体味||a.私处气味){
    if(a.体味)html+='<div class="d-text"><b style="color:var(--c-gold)">体味</b> '+esc(a.体味)+'</div>';
    if(a.私处气味)html+='<div class="d-text"><b style="color:var(--c-gold)">私处气味</b> '+esc(a.私处气味)+'</div>';
  }
  if(a.名器描述)html+='<div class="d-text"><b style="color:var(--c-powder)">名器详解</b> '+esc(a.名器描述)+'</div>';
  // 核心色情点——可折叠（默认收起只显示标题，点击展开长文），避免详情面板被长文撑爆
  if(sx.色情点&&sx.色情点.length){
    html+='<div class="psy-row" style="margin-bottom:6px"><span class="psy" style="color:var(--c-danger)">🔥 核心色情点</span></div>';
    for(var i=0;i<sx.色情点.length;i++){
      var seg=sx.色情点[i];
