/* 生理状态 → 外在表现映射（与"生理数值规范与限制"世界书一致） */
function physioDesc(c){
  var out=[];
  var body=obj(c.身体状态);
  var v=num(obj(body.阴道).湿润度,0);
  if(v>=80)out.push('阴道泛滥，水声明显');
  else if(v>=50)out.push('湿滑难耐，水声渐起');
  else if(v>=20)out.push('微润，有抵抗');
  else out.push('干涩，进入困难');
  var cs=num(obj(body.胸部).敏感度,0);
  if(cs>=90)out.push('胸部一碰即痉挛');
  else if(cs>=60)out.push('胸部轻碰即叫');
  else if(cs>=30)out.push('胸部触碰会轻颤');
  else out.push('胸部反应迟钝');
  var vs=num(obj(body.阴道).敏感度,0);
  if(vs>=90)out.push('阴道触之即失神边缘');
  else if(vs>=60)out.push('阴道一进就颤');
  else if(vs<30)out.push('阴道钝感');
  var pc=obj(c.生理周期);
  if(pc.月经状态==='经期')out.push('经期中，第1~3天不可战斗');
  else if(pc.月经状态==='排卵期')out.push('排卵期，欲望高涨');
  if(pc.怀孕)out.push('已怀孕'+num(pc.怀孕周数,0)+'周，禁止剧烈战斗');
  return out.join('；')||'正常';
}

