/* 名录 */
function renderRoster(){
  var d=S();var roles=obj(d.女性角色);var tgt=d.排班?d.排班.当前战斗目标:'';
  var keys=Object.keys(roles);
  var html='<div class="roster-head"><span>38 名女性 · 点击查看档案</span><span class="roster-count">'+keys.length+' 人在册</span></div>';
  // 筛选栏（全部/学生/老师/陪读妈妈/主角妈妈）
  var filters=['全部','学生','老师','陪读妈妈','主角妈妈'];
  html+='<div class="rf-bar">';
  for(var f=0;f<filters.length;f++){
    var fg=filters[f];
    html+='<span class="rf-btn'+(State.rosterFilter===fg?' active':'')+'" data-act="rfilter" data-filter="'+fg+'">'+fg+'</span>';
  }
  html+='</div>';
  // 内置角色分类表（38人固定；身份字段可能被 AI 覆盖丢失时兜底，防止划错分组）
  var ROLE_MAP={丽莎·伊万诺娃:'学生',何玉兰:'陪读妈妈',何雨珊:'学生',刘晶晶:'老师',叶春梅:'陪读妈妈',叶诗涵:'学生',周桂香:'陪读妈妈',周语桐:'学生',唐婉清:'老师',娜塔莎·伊万诺娃:'陪读妈妈',宋丽华:'陪读妈妈',宋佳凝:'学生',宋雅琴:'主角妈妈',张慧娟:'老师',李红梅:'老师',林汐瑶:'学生',林秀英:'陪读妈妈',沈若兰:'老师',王朵朵:'学生',王金凤:'陪读妈妈',白秋月:'陪读妈妈',白若薇:'学生',石小婉:'学生',石巧云:'陪读妈妈',秦可心:'学生',秦淑珍:'陪读妈妈',艾米丽·陈:'老师',苏婉如:'陪读妈妈',苏晚晴:'学生',赵雪晴:'老师',金顺姬:'陪读妈妈',陆芷晴:'学生',陆青霞:'陪读妈妈',陈淑芬:'陪读妈妈',陈雪梨:'学生',韩美娜:'学生',黎嘉欣:'学生',黎桂芳:'陪读妈妈'};
  function classifyRole(nm2,idt2){
    if(ROLE_MAP[nm2])return ROLE_MAP[nm2];
    var id=String(idt2||'');
    if(id.indexOf('主角妈妈')>=0||id.indexOf('主角')>=0)return '主角妈妈';
    if(id.indexOf('学生')>=0)return '学生';
    if(id.indexOf('老师')>=0||id.indexOf('班主任')>=0||id.indexOf('教师')>=0)return '老师';
    if(id.indexOf('陪读妈妈')>=0||id.indexOf('母亲')>=0||id.indexOf('妈妈')>=0)return '陪读妈妈';
    return '学生';
  }
  // 按身份分组（学生/老师/陪读妈妈/主角妈妈）
  var groups={学生:[],老师:[],陪读妈妈:[],主角妈妈:[]};
  for(var i=0;i<keys.length;i++){
    var nm=keys[i];
    var idt=String(obj(roles[nm]).身份||'');
    var cls=classifyRole(nm,idt);
    if(cls==='主角妈妈')groups.主角妈妈.push(nm);
    else groups[cls].push(nm);
  }
  var order=['学生','老师','陪读妈妈','主角妈妈'];
  for(var g=0;g<order.length;g++){
    var grp=order[g];
    if(State.rosterFilter!=='全部'&&State.rosterFilter!==grp)continue;
    var list=groups[grp];
    if(!list.length)continue;
    html+='<div class="roster-group"><div class="roster-group-title">'+grp+'（'+list.length+'）</div><div class="roster-grid">';
    for(var j=0;j<list.length;j++){
      var name=list[j];var c=obj(roles[name]);
      html+='<div class="roster-card'+(c.是否俘虏?' captured':'')+(name===tgt?' fighting':'')+'" data-act="detail" data-name="'+esc(name)+'">'
        +'<div class="rc-top"><span class="rc-name">'+esc(name)+'</span><span class="rc-role">'+esc(shortRole(c.身份))+'</span></div>'
        +'<div class="rc-tags">'
        +(c.是否俘虏?'<span class="rc-tag cap">俘</span>':'')
        +(num(c.欲望积压,0)>=60?'<span class="rc-tag hot">积压'+esc(c.欲望积压)+'</span>':'')
        +(num(c.压力值,0)>=60?'<span class="rc-tag pres">压力'+esc(c.压力值)+'</span>':'')
        +(name===tgt?'<span class="rc-tag fgt">战斗中</span>':'')
        +'</div>'
        +'<div class="rc-meta"><span class="fav" title="好感度（社交线，与缴械无关）">♥ '+esc(num(c.好感度,0))+'</span>'
        +'<span class="jx-lbl" title="缴械值（战斗线）">🔒 '+esc(num(c.缴械值,0))+'</span></div>'
        +'<div class="rc-hp"><div class="rc-track"><div class="rc-fill" style="width:'+clamp(c.缴械值,0,100)+'%;background:'+(num(c.缴械值,0)>=100?'var(--c-accent)':num(c.缴械值,0)>=60?'var(--c-gold)':'var(--c-info)')+'"></div></div><span class="rc-num">'+esc(c.缴械值||0)+'</span></div>'
        +'<div class="rc-sub">'+esc(c.省份||'')+' · '+esc(String(c.方言||'').slice(0,10))+(String(c.方言||'').length>10?'…':'')+'</div>'
        +'</div>';
    }
    html+='</div></div>';
  }
  return html;
}

