/* 主渲染 */
function render(){
  var loadingEl=document.getElementById('sb-loading');
  var bodyEl=document.getElementById('sb-body');
  if(!bodyEl)return;
  if(State.loading){loadingEl.style.display='';bodyEl.style.display='none';return}
  loadingEl.style.display='none';bodyEl.style.display='';
  var d=S();var tgt=d.排班?d.排班.当前战斗目标:'';
  var captives=0;var roles=obj(d.女性角色);
  for(var k in roles){if(roles[k]&&roles[k].是否俘虏)captives++}
  var panelHtml='';
  if(State.detail){panelHtml=renderDetail(State.detail)}
  else if(State.view==='roster'){panelHtml=renderRoster()}
  else if(State.view==='schedule'){panelHtml=renderSchedule()}
  else if(State.view==='subjects'){panelHtml=renderSubjects()+renderSkills()}
  else{panelHtml=renderSkills()}
  var tabs='<div class="tabs">'
    +'<div class="tab'+(State.view==='roster'?' active':'')+'" data-act="view" data-view="roster">名录'+(captives>0?' <span style="color:var(--c-accent)">（俘虏'+captives+'）</span>':'')+'</div>'
    +'<div class="tab'+(State.view==='subjects'?' active':'')+'" data-act="view" data-view="subjects">学业</div>'
    +'<div class="tab'+(State.view==='schedule'?' active':'')+'" data-act="view" data-view="schedule">今日排班</div>'
    +'<div class="tab'+(State.view==='skills'?' active':'')+'" data-act="view" data-view="skills">技能</div>'
    +'</div>';
  bodyEl.innerHTML=renderHeader()+(tgt?renderBattle():'')+tabs+'<div class="panel">'+panelHtml+'</div>';
}

/* 事件 */
function bindEvents(){
  var root=document.getElementById('sb-root');
  if(!root)return; // 元素未就绪时跳过绑定,不中断初始化
  root.addEventListener('click',function(e){
    var t=e.target;
    while(t&&t!==root){
      var act=t.getAttribute&&t.getAttribute('data-act');
      if(act){
        if(act==='view'){State.view=t.getAttribute('data-view');State.detail='';render()}
        else if(act==='detail'){State.detail=t.getAttribute('data-name');render()}
        else if(act==='back'){State.detail='';render()}
        else if(act==='rfilter'){State.rosterFilter=t.getAttribute('data-filter');render()}
        else if(act==='toggle-skill'){
          var sk=t.getAttribute('data-skill');
          var idx=State.selSkills.indexOf(sk);
          if(idx>=0){State.selSkills.splice(idx,1)}
          else if(State.selSkills.length<3){State.selSkills.push(sk)}
          render();
        }
        else if(act==='theme'){ydsToggleTheme()}
        else if(act==='bg'){ydsSbToggleBg()}
        else if(act==='send-round'){
          var action=(document.getElementById('action-input')||{}).value||'';
          State.actionText=action;
          sendRoundCommand(action);
        }
        return;
      }
      t=t.parentNode;
    }
  });
  root.addEventListener('input',function(e){
    var el=e.target;
    if(el&&el.id==='action-input'){State.actionText=el.value}
  });
}

/* 发起本回合：将进攻指令写入酒馆输入框 */
function findHostTextarea(){
  for(var i=0;i<TH_HOSTS.length;i++){
    try{
      var doc=TH_HOSTS[i].document;
      if(doc){
        var el=doc.querySelector('#send_textarea textarea')||doc.querySelector('textarea#send_textarea')||doc.querySelector('#send_form textarea');
        if(el)return el;
      }
    }catch(e){}
  }
  return null;
}
function sendRoundCommand(action){
  var d=S();var tgt=d.排班?d.排班.当前战斗目标:'';
  var skills=State.selSkills.slice();
  var skillText=skills.length?('使用技能：'+skills.join('、')):'不使用技能（纯体力进攻）';
  var cmd='【本回合进攻】目标：'+tgt+'。'+skillText+(action?'。攻法：'+action:'');
  var input=findHostTextarea();
  if(input){
    input.value=cmd;
    try{input.dispatchEvent(new Event('input',{bubbles:true}))}catch(e){}
    try{input.focus()}catch(e){}
    State.actionText='';State.selSkills=[];
  }else{
    State.actionText='';
    State.selSkills=[];
  }
  render();
}

/* 初始化 */
(function init(){
  bindEvents();
  // 事件驱动刷新（skill 规范：MESSAGE_UPDATED 300ms 防抖 + MESSAGE_RECEIVED 1s 兜底 + isRefreshing 防重入，禁止轮询——轮询会重置用户展开的详情/抽屉）
  var _refreshing=false;
  var doRefresh=function(){
    if(_refreshing)return;
    _refreshing=true;
    setTimeout(function(){try{refresh()}catch(e){};_refreshing=false},300);
  };
  try{if(typeof tavern_events==='object'&&tavern_events.MESSAGE_UPDATED&&typeof eventOn==='function'){eventOn(tavern_events.MESSAGE_UPDATED,doRefresh)}}catch(e){}
  try{if(typeof eventOn==='function'){eventOn('GENERATION_ENDED',doRefresh);eventOn('MESSAGE_EDITED',doRefresh);eventOn('mag_variable_update_ended',doRefresh);eventOn('MESSAGE_RECEIVED',function(){setTimeout(doRefresh,1000)})}}catch(e){}
  // ★数据变化检测兜底（事件在消息内联环境可能不可用）：每 3 秒读中继/最新数据，仅当 战斗状态/当前目标/体力/性欲/缴械值 等关键值变化才 refresh——
  // 与"无差别轮询"不同：无变化不重绘，用户展开的详情/抽屉不会被重置（规避 skill 坑#8）
  var _lastSnap='';
  try{
    setInterval(function(){
      try{
        if(document.hidden)return;
        var st3=readStatData();
        var pb3=obj(st3.排班);
        var p3=obj(st3.玩家);
        var tgt3=pb3.当前战斗目标||'';
        var c3=tgt3&&tgt3!=='多人'?(obj(st3.女性角色)[tgt3]||{}):{};
        var snap=(pb3.战斗状态||'')+'|'+tgt3+'|'+num(pb3.战斗&&pb3.战斗.回合,0)+'|'+num(p3.体力,0)+'|'+num(p3.性欲,0)+'|'+num(p3.勃起度,0)+'|'+num(c3.缴械值,-1)+'|'+num(c3.欲望积压,-1)+'|'+num(c3.压力值,-1)+'|'+num(c3.好感度,-1);
        if(snap!==_lastSnap){_lastSnap=snap;doRefresh();}
      }catch(e2){}
    },3000);
  }catch(e3){}
  window.addEventListener('message',function(e){
    try{
      var data=e.data;
      if(data&&data.type==='yds-mvu-stat-data'&&data.stat_data){
        var mesId=resolveMessageId();
        if(mesId>=0&&typeof data.messageId==='number'&&data.messageId>=0&&data.messageId!==mesId)return;
        if(hasData(data.stat_data)){
          cachedStatFromBridge=data.stat_data;
          State.data=deepMergeStat(DEFAULT_STAT,data.stat_data);
          State.loading=false;render();
        }
        return;
      }
      var t=(data&&data.type)||data||'';
      if(typeof t==='string'&&(t.indexOf('generation_ended')>=0||t.indexOf('message_edit')>=0))autoRefresh();
    }catch(x){}
  });
  var embedded=parseEmbeddedStat();
  if(embedded){cachedStatFromBridge=embedded;State.data=deepMergeStat(DEFAULT_STAT,embedded)}
  requestStatFromBridge();refresh();
})();
function refresh(){
  var stat=readStatData();
  if(hasData(stat)){State.data=stat;State.loading=false}
  try{advancePhysioIfNewDay()}catch(e){} // 跨日推进失败不影响渲染
  try{ensureTodaySchedule()}catch(e){} // 今日排班为空则自动生成全天 4 时段（上午=妈妈+没课老师/下午场=全体/晚场=学生为主/深夜=全体）
  render();
  waitForReadableStat(6000,function(realStat){
    if(hasData(realStat)){State.data=realStat;State.loading=false}
    try{advancePhysioIfNewDay()}catch(e){}
    try{ensureTodaySchedule()}catch(e){}
    render();requestStatFromBridge();
  });
}

/* 今日排班自动生成：今日场次为空时，按【排班规则】24 小时全覆盖生成 4 时段对阵表（上午=妈妈+没课老师/下午场=放学后全体/晚场=学生为主/深夜=全体） */
function ensureTodaySchedule(){
  try{
    var d=S();if(!hasData(d))return;
    var pb=obj(d.排班);
    var s=obj(pb.今日场次);
    if(Object.keys(s).length>0)return; // 今日已有排班
    var chars=d.女性角色||{};
    var mothers=[],teachers=[],students=[];
    for(var nm in chars){
      var c=chars[nm];
      if(!c||typeof c!=='object')continue;
      var idt=String(c.身份||'');
      if(idt.indexOf('陪读妈妈')>=0)mothers.push(nm);
      else if(idt.indexOf('学生')>=0)students.push(nm);
      else if(idt.indexOf('老师')>=0||idt.indexOf('班主任')>=0)teachers.push(nm);
    }
    function pick(arr,n){
      var a=arr.slice(),out=[];
      while(a.length&&out.length<n){var i=Math.floor(Math.random()*a.length);out.push(a.splice(i,1)[0]);}
      return out;
    }
    // 24 小时全覆盖（按【排班规则】使用时段）：上午=妈妈+没课老师；下午场=放学后全体；晚场=学生为主；深夜=全体
    var all=mothers.concat(teachers,students);
    var am=pick(mothers.concat(teachers),1+Math.floor(Math.random()*2)); // 上午（上课时间，在校者不可用）
    var noon=pick(all,1+Math.floor(Math.random()*2)); // 下午场（放学后，全体可用）
    var ev=pick(students.concat(mothers),1+Math.floor(Math.random()*2)); // 晚场（晚自习结束，学生为主+妈妈）
    var night=pick(all,1+Math.floor(Math.random()*2)); // 深夜（22:30 后，全体可用）
    if(am.length)s['上午']={参与者:am.join('、'),结果:'未开战',是否参战:false};
    if(noon.length)s['下午场']={参与者:noon.join('、'),结果:'未开战',是否参战:false};
    if(ev.length)s['晚场']={参与者:ev.join('、'),结果:'未开战',是否参战:false};
    if(night.length)s['深夜']={参与者:night.join('、'),结果:'未开战',是否参战:false};
    pb.今日场次=s;
    // 持久化写回（TH replaceVariables 是完全替换语义，必须读完整表→更新 stat_data→写回完整表，保留 schema/initialized_lorebooks）
    try{
      var Mvu4=getMvu();
      if(Mvu4&&typeof Mvu4.getMvuData==='function'&&typeof Mvu4.replaceMvuData==='function'){
        var opt4=getMessageOption();
        var full4=Mvu4.getMvuData(opt4);
        if(full4&&typeof full4==='object'){
          if(full4.stat_data===undefined&&(full4.排班!==undefined||full4.玩家!==undefined||full4.女性角色!==undefined||full4.时间!==undefined))full4={stat_data:full4};
          full4.stat_data=d;
          Mvu4.replaceMvuData(full4,opt4);
        }
      }
    }catch(e2){}
  }catch(e){console.error('ensureSchedule',e)}
}

/* 跨日推进：日期变化时执行生理周期/体力/冷却推进（与"生理数值规范与限制"世界书一致） */
function advancePhysioIfNewDay(){
  try{
    var d=S();if(!hasData(d))return;
    var t=obj(d.时间);var today=String(t.日期||'');
    if(!today)return;
    var p=obj(d.玩家);
    var last=obj(p.生理).上次推进日期||'';
    if(last===today)return; // 今天已推进
    var ph=obj(p.生理);
    // 玩家：体力恢复+40、性欲+10、射精冷却清零（新的一天）
    p.体力=clamp(num(p.体力,0)+40,0,100);
    p.性欲=clamp(num(p.性欲,0)+10,0,100);
    ph.射精冷却剩余=0;
    ph.今日射精次数=0;
    ph.上次推进日期=today;
    // 她方：月经日+1（到周期天数重置），更新月经状态
    var chars=d.女性角色||{};
    for(var nm in chars){
      var c=chars[nm];
      if(!c||typeof c!=='object'||!c.生理周期)continue;
      var pc=c.生理周期;
      if(pc.怀孕)continue; // 怀孕期间月经冻结
      var day=num(pc.月经日,1)+1;
      var cycle=num(pc.周期天数,28);
      if(day>cycle)day=1;
      pc.月经日=day;
      // 状态区间：1-5经期 / 6-11卵泡 / 12-16排卵 / 17+黄体
      if(day<=5)pc.月经状态='经期';
      else if(day<=11)pc.月经状态='卵泡期';
      else if(day<=16)pc.月经状态='排卵期';
      else pc.月经状态='黄体期';
      // 经期结束湿润度重置，排卵期欲望提升
      if(day<=5){obj(obj(c.身体状态).阴道).湿润度=10}
      else if(day>=12&&day<=16){c.欲望积压=clamp(num(c.欲望积压,0)+5,0,100)}
    }
    // 跨日推进持久化（读完整表→更新 stat_data→写回完整表，保留 schema/initialized_lorebooks）
    try{
      var Mvu4=getMvu();
      if(Mvu4&&typeof Mvu4.getMvuData==='function'&&typeof Mvu4.replaceMvuData==='function'){
        var opt4=getMessageOption();
        var full4=Mvu4.getMvuData(opt4);
        if(full4&&typeof full4==='object'){
          if(full4.stat_data===undefined&&(full4.排班!==undefined||full4.玩家!==undefined||full4.女性角色!==undefined||full4.时间!==undefined))full4={stat_data:full4};
          full4.stat_data=d;
          Mvu4.replaceMvuData(full4,opt4);
        }
      }
    }catch(e3){}
  }catch(e){console.error('advancePhysio',e)}
}
</script>
</body>
