<style>
:root{
  --bg-0:#121218;--bg-1:#1b1b23;--bg-card:rgba(30,30,37,.92);
  --c-text:#e8e6e1;--c-dim:#9b988f;--c-dim2:#6d6a62;
  --c-accent:#e0525e;--c-gold:#d9a441;--c-success:#59c98d;--c-danger:#ff5c5c;
  --c-warn:#e0b45c;--c-info:#6aa8d8;--c-powder:#f5a3b7;--c-border:rgba(255,255,255,.09);
  --font:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;
  --fs-xs:clamp(10px,2vw,11px);--fs-sm:clamp(11px,2.2vw,12px);--fs-base:clamp(12px,2.5vw,13px);--fs-md:clamp(13px,2.8vw,15px);
}
*{box-sizing:border-box;margin:0;padding:0;user-select:none;-webkit-tap-highlight-color:transparent}
html,body{font-family:var(--font);color:var(--c-text);background:transparent;font-size:var(--fs-base);line-height:1.5}
.battleui{width:100%;max-width:760px;margin:0 auto;background:linear-gradient(160deg,var(--bg-0),var(--bg-1));border:1px solid var(--c-border);border-radius:10px;overflow:hidden;box-shadow:0 4px 16px rgba(0,0,0,.45)}
.bu-head{display:flex;align-items:center;justify-content:space-between;padding:10px 14px;background:linear-gradient(120deg,rgba(224,82,94,.18),rgba(224,82,94,.05));border-bottom:1px solid rgba(224,82,94,.2)}
.bu-title{font-size:15px;font-weight:800;color:var(--c-accent)}
.bu-state{font-size:12px;padding:2px 10px;border-radius:999px;background:rgba(255,255,255,.06);color:var(--c-dim)}
.bu-state.进行中{color:var(--c-accent);background:rgba(224,82,94,.15)}
.bu-state.已结算{color:var(--c-success)}
.bu-empty{padding:28px 14px;text-align:center;color:var(--c-dim);font-size:13px}
.bu-empty .dim{font-size:11px;opacity:.65;margin-top:6px}
.battle{padding:10px 12px;margin:10px 14px 0;border-radius:9px;border:1px solid rgba(224,82,94,.25);background:linear-gradient(120deg,rgba(224,82,94,.08),rgba(224,82,94,.02) 55%)}
/* 多人目标九宫格：网格罗列 + 整卡可点选目标 */
.battle-grid-multi{display:grid;grid-template-columns:repeat(auto-fill,minmax(205px,1fr));gap:8px;margin:10px 14px 0}
.battle-grid-multi .battle{margin:0;cursor:pointer;transition:border-color .18s,box-shadow .18s}
.battle-grid-multi .battle:hover{border-color:rgba(217,164,65,.55)}
.battle-sel{border-color:var(--c-gold)!important;box-shadow:0 0 0 2px rgba(217,164,65,.35)!important}
.battle-grid-multi .battle-yes{margin-top:8px}
.battle-head{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px}
.battle-name{font-size:14px;font-weight:700;color:var(--c-accent)}
.battle-tag{font-size:11px;padding:1px 8px;border-radius:999px;background:rgba(224,82,94,.15);color:var(--c-accent)}
.hp-row{display:flex;align-items:center;gap:8px}
.hp-label{font-size:11px;color:var(--c-dim2);width:64px;flex-shrink:0}
.hp-track{flex:1;height:10px;border-radius:5px;background:rgba(255,255,255,.08);overflow:hidden}
.hp-fill{height:100%;border-radius:5px;transition:width .4s ease}
.hp-num{font-size:12px;font-weight:600;min-width:56px;text-align:right}
.battle-grid{display:flex;flex-wrap:wrap;gap:4px 16px;margin-top:8px;font-size:12px;color:var(--c-dim)}
.voice-box{margin-top:6px;padding:7px 10px;border-radius:8px;background:rgba(245,163,183,.08);border:1px solid rgba(245,163,183,.2);font-size:12px;color:var(--c-powder);font-style:italic;line-height:1.5}
.voice-box .vl{font-size:10px;color:var(--c-dim2);font-style:normal;display:block;margin-bottom:2px}
/* 战斗控制 */
.battle-ctrl{margin:10px 14px 14px;padding:10px 12px;border-radius:9px;border:1px solid var(--c-gold);background:linear-gradient(120deg,rgba(217,164,65,.08),rgba(217,164,65,.02) 55%)}
.battle-ctrl-title{font-size:12px;font-weight:700;color:var(--c-gold);margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:4px}
/* ===== 主题系统: dark(默认) / glass(磨砂玻璃) / light(亮色) ===== */
.battleui[data-theme="light"]{
  --bg-0:#f7f5ef;--bg-1:#eeebe3;--bg-card:rgba(255,255,255,.96);
  --c-text:#26251f;--c-dim:#6f6c62;--c-dim2:#9c988c;
  --c-accent:#c2404a;--c-gold:#a37412;--c-success:#2f8f62;--c-danger:#d64545;
  --c-warn:#a3742a;--c-info:#3f77a3;--c-powder:#b8587f;
  --c-border:rgba(0,0,0,.14);
}
.battleui[data-theme="glass"]{
  --bg-0:rgba(16,16,22,.78);--bg-1:rgba(24,24,32,.82);--bg-card:rgba(30,30,38,.66);
  --c-text:#f5f3ec;--c-dim:#c4c0b4;--c-dim2:#a09c90;
  --c-accent:#ff7d88;--c-gold:#e8b84f;--c-success:#6fd8a4;--c-danger:#ff7a7a;
  --c-warn:#f0c060;--c-info:#8fc1e8;--c-powder:#ffb8ca;
  --c-border:rgba(255,255,255,.18);
}
.battleui[data-theme="glass"] .battle,.battleui[data-theme="glass"] .battle-ctrl,.battleui[data-theme="glass"] .skill-card,.battleui[data-theme="glass"] .item-card,.battleui[data-theme="glass"] .hero-card,.battleui[data-theme="glass"] .battle-log,.battleui[data-theme="glass"] .her-skill-card,.battleui[data-theme="glass"] .heal-btn,.battleui[data-theme="glass"] .voice-box,.battleui[data-theme="glass"] .physio-strip{
  backdrop-filter:blur(18px) saturate(1.3);-webkit-backdrop-filter:blur(18px) saturate(1.3);
}
/* ===== 主题系统 v2: dark(深色·默认) / light(浅色) / glass(磨砂玻璃) / contrast(强对比) / pink(粉色) / blue(蓝色) / gold(金色) ===== */
/* 强对比：纯黑底+亮色高饱和，字重/字号加大，最大可读性 */
.battleui[data-theme="contrast"]{
  --bg-0:#000000;--bg-1:#0a0a0c;--bg-card:#101014;
  --c-text:#ffffff;--c-dim:#e6e6e6;--c-dim2:#bfbfbf;
  --c-accent:#ffcc00;--c-gold:#ffd700;--c-success:#00ff88;--c-danger:#ff4d4d;
  --c-warn:#ffcc44;--c-info:#00ccff;--c-powder:#ff9ad5;
  --c-border:rgba(255,255,255,.35);
  --fs-xs:clamp(10px,2vw,12px);--fs-sm:clamp(11px,2.2vw,13px);--fs-base:clamp(13px,2.6vw,15px);--fs-md:clamp(14px,2.9vw,16px);
}
.battleui[data-theme="contrast"] .battle-btn{font-weight:800;border:2px solid #fff}
.battleui[data-theme="contrast"] .skill-card,.battleui[data-theme="contrast"] .item-card,.battleui[data-theme="contrast"] .hero-card,.battleui[data-theme="contrast"] .battle-log{border-width:1.5px}
/* 粉色：浅粉底+深玫红字+圆体，柔美浪漫 */
.battleui[data-theme="pink"]{
  --bg-0:#fff0f5;--bg-1:#ffe4ee;--bg-card:#fff8fb;
  --c-text:#5c2433;--c-dim:#a0677a;--c-dim2:#c28fa2;
  --c-accent:#e0457c;--c-gold:#c98a2e;--c-success:#4a9e7a;--c-danger:#e04545;
  --c-warn:#c07a2e;--c-info:#6a8fc9;--c-powder:#e77fa3;
  --c-border:rgba(200,80,130,.22);
  --font:"Yuanti SC","YouYuan","PingFang SC","Microsoft YaHei",sans-serif;
}
.battleui[data-theme="pink"] .bu-head{background:linear-gradient(120deg,rgba(224,69,124,.16),rgba(224,69,124,.04));border-bottom-color:rgba(224,69,124,.25)}
.battleui[data-theme="pink"] .battle-btn{background:linear-gradient(90deg,#e0457c,#c2356a)}
.battleui[data-theme="pink"] .battle-btn.alt{background:linear-gradient(90deg,#c98a2e,#a37412)}
/* 蓝色：深蓝底+冰蓝字+白强调，冷静深邃 */
.battleui[data-theme="blue"]{
  --bg-0:#0d1626;--bg-1:#15203a;--bg-card:rgba(21,32,58,.92);
  --c-text:#eaf2ff;--c-dim:#a8c0e8;--c-dim2:#7d93b8;
  --c-accent:#5ab0ff;--c-gold:#e8c060;--c-success:#5ad6a0;--c-danger:#ff6a6a;
  --c-warn:#f0c060;--c-info:#7ac8ff;--c-powder:#ffb0d0;
  --c-border:rgba(120,170,255,.22);
}
.battleui[data-theme="blue"] .bu-head{background:linear-gradient(120deg,rgba(90,176,255,.18),rgba(90,176,255,.04));border-bottom-color:rgba(90,176,255,.3)}
.battleui[data-theme="blue"] .battle-btn{background:linear-gradient(90deg,#3f8fe0,#2f6fb8)}
/* 金色：黑金底+衬线体，贵气奢华 */
.battleui[data-theme="gold"]{
  --bg-0:#1a1408;--bg-1:#261d0c;--bg-card:rgba(38,29,12,.94);
  --c-text:#f5ead0;--c-dim:#cbb98a;--c-dim2:#9c8c60;
  --c-accent:#e8b64c;--c-gold:#ffd970;--c-success:#8fd4a0;--c-danger:#ff8a6a;
  --c-warn:#f0c060;--c-info:#a0c8f0;--c-powder:#f0c0a0;
  --c-border:rgba(232,182,76,.28);
  --font:"Songti SC","STSong","SimSun","PingFang SC","Microsoft YaHei",serif;
}
.battleui[data-theme="gold"] .bu-head{background:linear-gradient(120deg,rgba(232,182,76,.2),rgba(232,182,76,.04));border-bottom-color:rgba(232,182,76,.35)}
.battleui[data-theme="gold"] .battle-btn{background:linear-gradient(90deg,#c9a03c,#a3822e)}
.battleui[data-theme="gold"] .battle-btn.alt{background:linear-gradient(90deg,#8f6f20,#6d5418)}

.theme-btn,.bg-btn{cursor:pointer;font-size:12px;font-weight:700;opacity:1;transition:opacity .15s;padding:3px 9px;border-radius:999px;background:rgba(255,255,255,.1);border:1px solid var(--c-border);color:var(--c-text);white-space:nowrap}
.theme-btn:hover{opacity:.8;border-color:var(--c-gold)}
.bg-btn:hover{opacity:.85;border-color:var(--c-info)}
/* ===== 动态背景系统: static(默认) / aurora(极光流动) / rainbow(彩虹流动) ===== */
.battleui[data-bg="aurora"]{background:linear-gradient(135deg,var(--bg-0),var(--bg-1),rgba(255,255,255,.06),var(--bg-1));background-size:320% 320%;animation:ydsAurora 16s ease infinite}
.battleui[data-bg="rainbow"]{background:linear-gradient(135deg,#ff6b8a,#b06bff,#4fb3ff,#3dd68c,#ffd76b,#ff8a5c,#ff6b8a);background-size:420% 420%;animation:ydsAurora 18s ease infinite}
.battleui[data-theme="light"][data-bg="rainbow"],.battleui[data-theme="pink"][data-bg="rainbow"]{background:linear-gradient(135deg,#ffe6ec,#e6e6ff,#e6fff0,#fffbe6,#ffe9d6,#ffe6ec);background-size:420% 420%;animation:ydsAurora 18s ease infinite}
@keyframes ydsAurora{0%{background-position:0% 50%}50%{background-position:100% 50%}100%{background-position:0% 50%}}
@media(prefers-reduced-motion:reduce){.battleui[data-bg="aurora"],.battleui[data-bg="rainbow"]{animation:none}}
/* 血条发光 + 低血量闪烁 */
.hp-fill{box-shadow:0 0 8px rgba(255,255,255,.22)}
.hp-fill.hp-low{animation:ydsLow 1s ease infinite}
@keyframes ydsLow{0%,100%{opacity:1;box-shadow:0 0 6px rgba(255,92,92,.4)}50%{opacity:.55;box-shadow:0 0 18px rgba(255,92,92,.95)}}
/* 经验满级闪光 */
.sc-exp i b.xp-full{animation:ydsXp 1s ease infinite}
@keyframes ydsXp{0%,100%{filter:brightness(1)}50%{filter:brightness(1.7)}}
.bu-head-r{display:flex;align-items:center;gap:8px;flex-wrap:wrap;justify-content:flex-end}
.legend{font-size:10px;color:var(--c-dim);background:rgba(255,255,255,.04);border-radius:6px;padding:5px 8px;margin-top:6px;line-height:1.7}
.api-note{font-size:10px;color:var(--c-info);background:rgba(106,168,216,.08);border:1px dashed rgba(106,168,216,.3);border-radius:6px;padding:5px 8px;margin-top:6px;line-height:1.6}
.mini-num{font-size:10px;color:var(--c-text);font-weight:700;margin-left:3px;min-width:16px;display:inline-block}

.battle-ctrl-title .rounds{font-size:10px;color:var(--c-dim2);font-weight:400}
.skill-sel{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:6px;margin-bottom:8px}
.skill-card{padding:7px 9px;border-radius:8px;background:rgba(255,255,255,.05);border:1px solid var(--c-border);cursor:pointer;transition:all .15s ease;position:relative}
.skill-card:hover{border-color:var(--c-gold)}
.skill-card.sel{border-color:var(--c-gold);background:rgba(217,164,65,.12)}
.skill-card.off{opacity:.4;pointer-events:none}
.skill-card .sc-top{display:flex;align-items:center;gap:6px;margin-bottom:3px}
.skill-card .sc-icon{font-size:16px}
.skill-card .sc-name{font-weight:700;font-size:12px;color:var(--c-text);flex:1}
.skill-card .sc-lv{font-size:10px;color:var(--c-gold);font-weight:700;background:rgba(217,164,65,.12);padding:1px 5px;border-radius:4px}
.skill-card .sc-dmg{font-size:12px;font-weight:700;color:var(--c-powder)}
.skill-card .sc-dmg small{font-size:10px;color:var(--c-dim2);font-weight:400}
.skill-card .sc-eff{font-size:10px;color:var(--c-dim);line-height:1.4;margin-top:2px}
.skill-card .sc-check{position:absolute;top:6px;right:6px;color:var(--c-gold);font-size:11px;display:none}
.skill-card.sel .sc-check{display:block}
.skill-card .sc-exp{font-size:9px;color:var(--c-dim2);margin-top:2px}
.skill-card .sc-exp i{display:inline-block;width:36px;height:3px;border-radius:2px;background:rgba(255,255,255,.08);overflow:hidden;vertical-align:middle;margin-right:3px}
.skill-card .sc-exp i b{display:block;height:100%;background:linear-gradient(90deg,var(--c-gold),#e8c77a)}
/* 道具栏 */
.item-bar{display:grid;grid-template-columns:repeat(auto-fill,minmax(96px,1fr));gap:6px;margin-bottom:8px}
.item-card{padding:6px 8px;border-radius:7px;background:rgba(255,255,255,.05);border:1px solid var(--c-border);cursor:pointer;transition:all .15s ease;text-align:center;position:relative}
.item-card:hover{border-color:var(--c-gold)}
.item-card.sel{border-color:var(--c-gold);background:rgba(217,164,65,.12)}
.item-card.off{opacity:.4;pointer-events:none}
.item-card .ic-name{font-size:11px;font-weight:700;color:var(--c-text)}
.item-card .ic-count{font-size:10px;color:var(--c-dim2);display:block}
.item-card .ic-eff{font-size:9px;color:var(--c-dim);display:block;margin-top:1px;line-height:1.3}
.item-card .ic-check{position:absolute;top:3px;right:5px;color:var(--c-gold);font-size:10px;display:none}
.item-card.sel .ic-check{display:block}
/* 恢复技能 */
.heal-bar{display:flex;gap:6px;margin-bottom:8px;flex-wrap:wrap}
.heal-btn{flex:1;min-width:110px;padding:7px 8px;border-radius:7px;background:rgba(89,201,141,.08);border:1px solid rgba(89,201,141,.25);cursor:pointer;transition:all .15s ease;text-align:center}
.heal-btn:hover{border-color:var(--c-success)}
.heal-btn.off{opacity:.4;pointer-events:none}
.heal-btn .hb-name{font-size:11px;font-weight:700;color:var(--c-success)}
.heal-btn .hb-eff{font-size:9px;color:var(--c-dim);display:block;margin-top:1px}
.heal-btn .hb-cd{font-size:9px;color:var(--c-warn);display:block}
/* BUFF/DEBUFF 徽章 */
.buff-row{display:flex;flex-wrap:wrap;gap:4px;margin-top:6px}
.buff-tag{font-size:10px;padding:1px 7px;border-radius:999px;line-height:1.6}
.buff-tag.buff{background:rgba(89,201,141,.12);color:var(--c-success);border:1px solid rgba(89,201,141,.25)}
.buff-tag.debuff{background:rgba(255,92,92,.12);color:var(--c-danger);border:1px solid rgba(255,92,92,.25)}
.buff-tag .bt-round{opacity:.7;font-size:9px}
/* 区域标题 */
.zone-title{font-size:11px;font-weight:700;color:var(--c-gold);margin:10px 0 6px;display:flex;align-items:center;gap:6px}
.zone-title:first-child{margin-top:0}
.action-input{width:100%;min-height:44px;padding:7px 10px;border-radius:7px;border:1px solid var(--c-border);background:rgba(255,255,255,.04);color:var(--c-text);font-size:12px;font-family:inherit;resize:vertical;box-sizing:border-box}
.action-input:focus{outline:none;border-color:var(--c-gold)}
.battle-btn{width:100%;margin-top:8px;padding:9px 0;border-radius:7px;border:none;background:linear-gradient(90deg,var(--c-accent),#c44550);color:#fff;font-size:13px;font-weight:700;cursor:pointer;transition:opacity .15s ease}
.battle-btn:hover{opacity:.9}
.battle-btn:disabled{opacity:.4;cursor:not-allowed}
.battle-btn.alt{background:linear-gradient(90deg,var(--c-gold),#b8892e)}
.battle-tip{font-size:10px;color:var(--c-dim2);margin-top:6px;line-height:1.6}
.formula{font-size:10px;color:var(--c-dim2);background:rgba(255,255,255,.04);border-radius:6px;padding:5px 8px;margin-top:6px;line-height:1.6}
/* 她的信息卡（RPG） */
.hero-card{margin:8px 0;padding:8px 10px;border-radius:8px;background:rgba(224,82,94,.06);border:1px solid rgba(224,82,94,.2)}
.hero-card .hc-title{font-size:11px;font-weight:700;color:var(--c-accent);margin-bottom:6px;display:flex;align-items:center;gap:6px}
.hero-card .hc-skill{margin-bottom:4px}
.hero-card .hc-skill .hs-name{font-size:12px;font-weight:700;color:var(--c-gold)}
.hero-card .hc-skill .hs-desc{font-size:10px;color:var(--c-dim);line-height:1.4;margin-top:1px}
.hero-card .hc-stat{display:grid;grid-template-columns:repeat(auto-fill,minmax(90px,1fr));gap:4px;margin-top:6px}
.hero-card .hc-stat .hs-item{background:rgba(255,255,255,.05);border-radius:5px;padding:3px 6px;text-align:center}
.hero-card .hc-stat .hs-item .k{font-size:9px;color:var(--c-dim2);display:block}
.hero-card .hc-stat .hs-item .v{font-size:12px;font-weight:700;color:var(--c-text)}
.hero-card .hc-stat .hs-item .v.atk{color:var(--c-danger)}
.hero-card .hc-stat .hs-item .v.def{color:var(--c-info)}
.hero-card .hc-stat .hs-item .v.buf{color:var(--c-success)}
/* 回合明细日志 */
.battle-log{margin:0 14px 14px;padding:8px 10px;border-radius:8px;background:rgba(255,255,255,.03);border:1px solid var(--c-border);max-height:220px;overflow-y:auto}
.log-title{font-size:11px;color:var(--c-dim2);letter-spacing:1px;margin-bottom:6px}
.log-item{font-size:11px;color:var(--c-dim);padding:5px 0;border-bottom:1px solid rgba(255,255,255,.05);line-height:1.6}
.log-item:last-child{border-bottom:none}
.log-item .rk{color:var(--c-gold);font-weight:700;display:inline-block;min-width:42px}
.log-item .atk{color:var(--c-powder);font-weight:700}
.log-item .def{color:var(--c-info)}
.log-item .dmg-detail{font-size:10px;color:var(--c-dim2);display:block;margin-left:42px}
.log-item .her-atk{color:var(--c-danger)}
.log-item .log-flavor{display:block;margin-left:42px;color:var(--c-dim);font-style:italic;font-size:10px;line-height:1.5}
.log-item .win{color:var(--c-success);font-weight:700}
.log-item .lose{color:var(--c-danger);font-weight:700}
.loading{text-align:center;padding:30px;color:var(--c-dim);font-size:var(--fs-md);animation:pulse 1.2s ease infinite}
@keyframes pulse{0%,100%{opacity:.5}50%{opacity:1}}
/* 她的信息区（跟男方对齐：技能卡/道具栏/恢复技能） */
.her-panel{margin:8px 0;display:grid;gap:6px}
.hp-title{font-size:11px;font-weight:700;color:var(--c-powder);display:flex;align-items:center;gap:6px;margin-bottom:2px}
.her-skill-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:6px}
.her-skill-card{padding:6px 8px;border-radius:7px;background:rgba(245,163,183,.07);border:1px solid rgba(245,163,183,.22)}
.her-skill-card.off{opacity:.45}
.her-skill-card .hsc-top{display:flex;align-items:center;gap:5px;margin-bottom:2px}
.her-skill-card .hsc-icon{font-size:14px}
.her-skill-card .hsc-name{font-weight:700;font-size:11px;color:var(--c-powder);flex:1}
