  if((rounds===0||num(pb.主角防守值,0)<=0)&&c){
    // 初始化：主角防守值=体力×1.2；她=档案上限
    var pDef=Math.round(num(obj(d.玩家).体力,80)*1.2);
    var herCap=herDefCap(c);
    pb.回合=0;
    pb.主角防守值=pDef;pb.主角防守值上限=pDef;
